Given $\underline{\epsilon}$, $\underline{\epsilon}'\in B^N_{\epsilon}$, the corresponding morphisms
\begin{gather*}
R_{\underline{\epsilon}},\,R_{\underline{\epsilon}'}\colon \ \tau_{\leq N}\mathscr{N}_{\varepsilon}^p(X,\bullet)\to C_{\mathscr{D}}^{2p-\bullet}(X,\mathbb{Z}(p))
\end{gather*}
induced by the perturbed KLM currents, are integrally homotopic in degrees~$\bullet<N$.

ny $Z\in Z^p(X,n)$ may be lifted to $c^p(X,n)$, and we may add degenerate cycles to any element of $c^p(X,n)$ to force it into $Z^p_{\infty,n}(X,n)$. The (well-defined) map given by this process is an isomorphism, and we shall tacitly equate $Z^p(X,n)$ and $Z^p_{\infty,n}(X,n)$ in what follows.

For each integer $l \leq n-1$, define $h^l\colon \square^{n+1}\rightarrow\square^n$ by
\begin{gather*}
h^l(z_1,\ldots,z_{n+1}):=\big(z_1,\ldots,z_{l},\tfrac{z_{l+1}z_{l+2}}{z_{l+1}+z_{l+2}-1},z_{l+3},\ldots,z_{n+1}\big)
\end{gather*}
and for $Z\in Z^p(X,n)$, define $H^l(Z):=(-1)^{l}\big(h^l\big)^{-1}(Z)\in Z^p(X,n+1)$. If $l\geq n$, set $H^l(Z)=0$. The map
\begin{gather*}
\phi:=\cdots\big(\mathrm{Id}-\big(\partial\circ H^l+H^l\circ \partial\big)\big)\circ(\mathrm{Id}-\big(\partial\circ H^{l-1}+H^{l-1}\circ \partial\big)\big)\circ \\
\hphantom{\phi:=}{} \cdots \circ\big(\mathrm{Id}-\big(\partial\circ H^0+H^0\circ \partial\big)\big)
\end{gather*}
stabilizes in any degree and so defines an endomorphism $\phi\colon Z^p(X,\bullet)\rightarrow Z^p(X,\bullet)$, which is visibly homotopic to the identity.

To determine its image, write (for any $Z\in Z^p(X,n)$)
\begin{gather*}
 \big(\partial \circ H^l\big)Z=\sum_{k=1}^{n-l-1}(-1)^{n-l+k+1}\partial_{n-k+1}^{\infty}Z\big(z_1,\ldots,\tfrac{z_{l+1}z_{l+2}}{z_{l+1}+z_{l+2}-1},\ldots,z_n\big) \\
\hphantom{\big(\partial \circ H^l\big)Z=}{}+\sum_{k=n-l+1}^{n}(-1)^{n-l+k}\partial_{n-k+1}^{\infty}Z\big(z_1,\ldots,\tfrac{z_{l}z_{l+1}}{z_{l}+z_{l+1}-1},\ldots,z_n\big)
\end{gather*}
and
\begin{gather*}
 \big(H^l\circ \partial\big)Z=\sum_{k=1}^{n}(-1)^{n-l+k}\partial_{n-k+1}^{\infty}Z\big(z_1,\ldots,\tfrac{z_{l+1}z_{l+2}}{z_{l+1}+z_{l+2}-1},\ldots,z_n\big),
\end{gather*}
where the notation means that we pull back (the equations defining) $\partial^{\infty}_{n-k+1}Z$ via $h^l$ (or $h^{l-1}$): $\square^n \to \square^{n-1}$. Thus we have
\begin{gather*}
 \big(\partial\circ H^l+H^l\circ \partial\big)Z=\sum_{k=n-l+1}^{n}(-1)^{n-l+k}\partial_{n-k+1}^{\infty}Z\big(z_1,\ldots,\tfrac{z_{l}z_{l+1}}{z_{l}+z_{l+1}-1},\ldots,z_n\big) \\
\hphantom{\big(\partial\circ H^l+H^l\circ \partial\big)Z=}{}+\sum_{k=n-l}^{n}(-1)^{n-l+k}\partial_{n-k+1}^{\infty}Z\big(z_1,\ldots,\tfrac{z_{l+1}z_{l+2}}{z_{l+1}+z_{l+2}-1},\ldots,z_n\big).
\end{gather*}
In particular, for $Z\in Z^p_{\infty,i}(X,\bullet)$, we have $\big(d\circ H^l+H^l\circ d\big)Z=0$ for $l \leq n-i-2$. For $l=n-i-1$, we find
\begin{gather*}
 Z':=Z-\big(\partial\circ H^l+H^l\circ\partial\big)Z = Z-\partial^{\infty}_{n-i}Z\big(z_1,\ldots,\tfrac{z_{n-i}z_{n-i+1}}{z_{n-i}+z_{n-i+1}-1},\ldots,z_n\big),
\end{gather*}
which belongs to $Z^p_{\infty,i-1}$. Applying $\big(\mathrm{Id}-\big(\partial\circ H^{l+1}+H^{l+1}\circ\partial\big)\big)$ then maps $Z'$ to some $Z''\in Z^p_{\infty,i-2}$, and so forth until finally we reach $Z^p_{\infty,0}(X,n)=\mathscr{N}^p(X,n)$. Since all the $\partial\circ H^l + H^l\circ \partial$ are zero on $Z^p_{\infty,0}$, $\phi|_{\mathscr{N}}$ gives the identity on normalized cycles.

We have thus constructed a morphism $\phi\colon Z^p(X,\bullet)\to \mathscr{N}^p(X,\bullet)$, whose composition with the inclusion $\mathscr{N}^p\hookrightarrow Z^p$ is homotopic to (resp. equal to) the identity on $Z^p$ (resp. $\mathscr{N}^p$); thus $\phi$ and the inclusion are both quasi-isomorphisms.

n any given $n$-``face'' ($\cong \big(\mathbb{P}^1\big)^n$) we have
\begin{gather*}
 D\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_n=\sum_{k=1}^n\sum_{l=1}^{k-1}(-1)^{l-1}(-1)^{k-1}\mathcal{R}^{\epsilon_1}_{z_1}\cup\cdots\cup D\mathcal{R}^{\epsilon_l}_{z_l}\cup\cdots\cup\mathcal{S}^{\epsilon_{k},\epsilon'_{k}}_{z_k}\cup\cdots\cup\mathcal{R}^{\epsilon'_n}_{z_n} \\
\hphantom{D\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_n=}{}+\sum_{k=1}^n\sum_{l=k+1}^n(-1)^{l}(-1)^{k-1}\mathcal{R}^{\epsilon_1}_{z_1}\cup\cdots\cup \mathcal{S}^{\epsilon_{k},\epsilon'_{k}}_{z_k}\cup\cdots\cup D\mathcal{R}^{\epsilon'_l}_{z_l}\cup\cdots\cup\mathcal{R}^{\epsilon'_n}_{z_n}\\
\hphantom{D\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_n=}{} +\sum_{k=1}^n\mathcal{R}^{\epsilon_1}_{z_1}\cup\cdots\cup D\mathcal{S}^{\epsilon_k,\epsilon'_k}_{z_k}\cup\cdots\cup\mathcal{R}^{\epsilon'_n}_{z_n}.
\end{gather*}

Noting that $D\mathcal{R}^{\epsilon}_{z_i}=-2\pi{\rm i}(\delta_{(z_i)},\delta_{(z_i)},0)=:-2\pi{\rm i} \Delta_{(z_i)}$ (which commutes with other triples) and $D\mathcal{S}^{\epsilon,\epsilon'}_{z_i}=\mathcal{R}^{\epsilon}_{z_i}-\mathcal{R}^{\epsilon'}_{z_i}$, we can rewrite this expression by applying the telescoping method and rearranging the order of the summation. Denoting $(-1)^{k-1}_l := \begin{cases} (-1)^{k-1}, & l>k, \\ (-1)^{k-2}, & l<k, \end{cases}$
\begin{gather*}
 D\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_n=2\pi{\rm i}\sum_{k=1}^n\sum_{l=1,\, l\neq k}^n(-1)^{l}(-1)^{k-1}_l\Delta_{(z_l)}\mathcal{R}^{\epsilon_1}_{z_1}\cup\cdots\cup\mathcal{S}^{\epsilon_{k},\epsilon'_{k}}_{z_k}\cup\cdots\cup\mathcal{R}^{\epsilon'_n}_{z_n} \\
\hphantom{D\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_n=}{} \text{(with the } l^{\rm th}\text{ term omitted, either before } k \text{ or after } k\text{)} \\
\hphantom{D\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_n=}{} +\sum_{k=1}^n\mathcal{R}^{\epsilon_1}_{z_1}\cup\cdots\cup \big(\mathcal{R}^{\epsilon_k}_{z_k}-\mathcal{R}^{\epsilon'_k}_{z_k}\big)\cup\cdots\cup\mathcal{R}^{\epsilon'_n}_{z_n} \\
\hphantom{D\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_n}{} =2\pi{\rm i}\sum_{l=1}^n(-1)^{l}\Delta_{(z_l)}\sum_{k=1,\, k\neq l}^n(-1)^{k-1}_l\mathcal{R}^{\epsilon_1}_{z_1}\cup\cdots\cup\mathcal{S}^{\epsilon_{k},\epsilon'_{k}}_{z_k}\cup\cdots\cup\mathcal{R}^{\epsilon'_n}_{z_n}
 +\mathcal{R}^{\underline{\epsilon}}_n-\mathcal{R}^{\underline{\epsilon'}}_n \\
\hphantom{D\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_n}{} =-(-1)^n\delta\big( \big\{\mathcal{S}^{\{\epsilon_1,\dots,\hat{\epsilon_l},\dots,\epsilon_n\},\{\epsilon'_1,\dots,\hat{\epsilon'_l},\dots,\epsilon'_n\}}_{n-1} \big\}_{l=1,\ldots,n; f(l)=0,\infty} \big)+\mathcal{R}^{\underline{\epsilon}}_n-\mathcal{R}^{\underline{\epsilon'}}_n.
\end{gather*}

This tells us
\begin{gather}\label{eq64}
D\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_n+(-1)^n\delta\big( \big\{\mathcal{S}^{\{\epsilon_1,\dots,\hat{\epsilon_l},\dots,\epsilon_n\},\{\epsilon'_1,\dots,\hat{\epsilon'_l},\dots,\epsilon'_n\}}_{n-1} \big\}_{l=1,\ldots,n; f(l)=0,\infty} \big)=\mathcal{R}^{\underline{\epsilon}}_n-\mathcal{R}^{\underline{\epsilon'}}_n
\end{gather}
holds on each $n$-face of $\big(\mathbb{P}^1\big)^n$. Thus $\mathbb{D}\mathcal{S}^{\underline{\epsilon},\underline{\epsilon'}}_{\Box}=\mathcal{R}^{\underline{\epsilon}}_{\Box}-\mathcal{R}^{\underline{\epsilon'}}_{\Box}$ holds.

ince $\mathscr{N}^p_{\varepsilon}(X,\bullet)\subset\mathscr{N}^p(X,\bullet)$, we have $H_n\big(\mathscr{N}^p_{\varepsilon}(X,\bullet)\big)$ maps to $H_n(\mathscr{N}^P(X,\bullet))=$ \linebreak ${\rm CH}^P(X,n)$ for every $\varepsilon$, hence there exists a natural map $\lim\limits_{\overrightarrow{\varepsilon}}H_n\big(\mathscr{N}^p_{\varepsilon}(X,\bullet)\big)\rightarrow {\rm CH}^p(X,n)$. Since $\bigcup\mathscr{N}^p_{\varepsilon}(X,\bullet)=\mathscr{N}^p(X,\bullet)$, this map is surjective. To show it is injective, consider $\xi\in {\rm CH}^p(X,n)$, and $\tilde{\xi}$, $\tilde{\xi}'$ be two representations of $\xi$ in the following sequence:
\begin{gather*}H_n\big(\mathscr{N}^p_{\varepsilon}(X,\bullet)\big)\rightarrow H_n\big(\mathscr{N}^p_{\varepsilon'}(X,\bullet)\big)\rightarrow\cdots\rightarrow {\rm CH}^p(X,n).\end{gather*}
We need to show that $\tilde{\xi}$ and $\tilde{\xi}'$ will eventually merge at some $\epsilon$, that is to say, $\bigcup\partial\mathscr{N}^p_{\varepsilon}(X,n+1)=\partial\mathscr{N}^p(X,n+1)$, which directly comes from the property of normalized cycle and $\bigcup\mathscr{N}^p_{\varepsilon}(X,\bullet)=\mathscr{N}^p(X,\bullet)$.
